import codecs
calls = []
def search(name):
    calls.append(name)
    if name == 'bad_result':
        return ()
codecs.register(search)
for name in ('Unknown-Codec', 'é' * 250, '💥' * 150):
    for attempt in range(2):
        try:
            codecs.lookup(name)
        except LookupError as error:
            assert type(error) is LookupError
            assert error.args == ('unknown encoding: ' + name,)
        else:
            assert False
try:
    codecs.lookup('bad-result')
except TypeError as error:
    assert type(error) is TypeError
    assert error.args == ('codec search functions must return 4-tuples',)
else:
    assert False
assert len(calls) == 7
print('diagnostics preserved')

import codecs
class Position:
    def __init__(self, value):
        self.value = value
    def __index__(self):
        print('index', self.value)
        return self.value
class Failure(Exception):
    pass
failure = Failure('guest failure')
for encoding, source, operation in (('ascii', '\u20acA', 'encode'), ('utf-8', b'\xffA', 'decode')):
    for result in (None, [], (), ('?',), ('?', 0, 1), ('?', 1.5), ('?', Position(3)), ('?', Position(-3)), ('?', Position(1 << 100)), (b'?', Position(-1)), (object(), Position(1)), ('?', Position(-1))):
        def handler(error):
            print('error', type(error).__name__, error.encoding, error.object, error.start, error.end, error.reason)
            return result
        codecs.register_error('return-boundaries', handler)
        try:
            print('result', getattr(codecs, operation)(source, encoding, 'return-boundaries'))
        except Exception as error:
            print(type(error).__name__, error.args)
    def raises(error):
        raise failure
    codecs.register_error('raised-failure', raises)
    try:
        getattr(codecs, operation)(source, encoding, 'raised-failure')
    except Failure as error:
        print('identity', error is failure)

import codecs
assert input() == 'ready'
class Pair(tuple):
    def __len__(self):
        raise AssertionError('virtual length')
    def __getitem__(self, index):
        raise AssertionError('virtual indexing')
def callback(*args):
    return result
def search(name):
    if name == 'result_contract':
        return (callback, callback, None, None)
codecs.register(search)
for operation in ('encode', 'decode'):
    for result in (None, [], (), (None,), (None, None, None), Pair(('value', object()))):
        try:
            print(operation, getattr(codecs, operation)(None, 'result-contract'))
        except TypeError as error:
            print(operation, type(error).__name__, error.args, getattr(error, '__notes__', None))
print('result validation verified')
